import{_ as n,o as t,c as i,ah as s}from"./chunks/framework.Bja9t6Wf.js";const m=JSON.parse('{"title":"Drehbuch-Update: Szene 31 - Die Kunst der Gefälligkeit","description":"","frontmatter":{},"headers":[],"relativePath":"logbuch/szene-mazenatentum.md","filePath":"logbuch/szene-mazenatentum.md"}'),r={name:"logbuch/szene-mazenatentum.md"};function a(h,e,l,o,u,d){return t(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="drehbuch-update-szene-31-die-kunst-der-gefalligkeit" tabindex="-1">Drehbuch-Update: Szene 31 - Die Kunst der Gefälligkeit <a class="header-anchor" href="#drehbuch-update-szene-31-die-kunst-der-gefalligkeit" aria-label="Permalink to &quot;Drehbuch-Update: Szene 31 - Die Kunst der Gefälligkeit&quot;">​</a></h1><p><strong>STIL:</strong> Hochglanz-Ästhetik. Ein helles, modernes Privatmuseum (ähnlich der Heidi Horten Collection in Wien). Die Kamera gleitet über sündhaft teure Gemälde von Warhol und Picasso.</p><p><strong>BESETZUNG:</strong></p><ul><li><strong>Heidi Horten:</strong> Birgit Minichmayr (in einem extravaganten Designerkostüm, behängt mit Perlen)</li><li><strong>Der junge Reporter:</strong> Ein leicht eingeschüchterter Mann in einem schlecht sitzenden Anzug.</li></ul><hr><p><strong>INT. PRIVATMUSEUM - TAG</strong></p><p>Heidi (Minichmayr) steht vor einem riesigen, bunten Gemälde. Sie hält ein Glas Champagner, in dem die Kohlensäure fast schon rhythmisch perlt.</p><p><strong>HEIDI</strong> (mit tiefer, rauchiger Stimme und leichtem Wiener Akzent) Schauen Sie sich das an, Schatzi. Ein Picasso. Wissen Sie, was das Besondere an einem Picasso ist? Er ist nicht einfach nur Farbe auf Leinwand. Er ist ein Statement. Er sagt: &quot;Ich kann mir die Realität leisten, die ich will.&quot;</p><p><strong>REPORTER</strong> (macht sich Notizen) Beeindruckend, Frau Horten. Aber viele fragen sich... woher kommt die Leidenschaft für die Kunst? Und gibt es Parallelen zu Ihrem... nun ja... politischen Engagement?</p><p><strong>HEIDI</strong> (lacht leise, ein kehliges Lachen) Aber geh! Politik, Kunst... das ist doch alles dasselbe, mein Lieber. Es geht um das <em>Mäzenatentum</em>. Ein Künstler braucht einen Rahmen, damit sein Werk wirkt. Und eine Partei? Die braucht eben auch einen Rahmen, damit sie... ordentlich arbeiten kann.</p><p>Sie tritt einen Schritt näher an ein Porträt ihres verstorbenen Mannes Helmut heran.</p><p><strong>HEIDI</strong> Helmut hat immer gesagt: &quot;Heidi, ein Kaufhaus ist wie ein Museum. Man muss den Leuten zeigen, was sie begehren sollen.&quot; Ich mache jetzt nichts anderes. Ich zeige der Welt, wie ein schönes Österreich aussieht. Und wenn das ein paar Spenden hier und da erfordert...</p><p><strong>REPORTER</strong> Kritiker nennen es Einflussnahme. Oder Spendenstückelung, um den Rechnungshof zu umgehen.</p><p><strong>HEIDI</strong> (sieht ihn direkt an, ihre Augen blitzen kühl) Stückelung? Was für ein hässliches Wort. Ich nenne es <em>Pointillismus</em>. Wie bei Seurat! Viele kleine Punkte ergeben erst aus der Distanz das große, glanzvolle Bild. Wer nur die einzelnen Punkte sieht, hat keinen Sinn für die Ästhetik des Ganzen.</p><p>Sie nimmt einen Schluck Champagner.</p><p><strong>HEIDI</strong> Wissen Sie, Schatzi... Kunst am Bau ist gut. Aber Kunst am <em>Staat</em>? Das ist die wahre Königsdisziplin.</p><p><strong>FADE TO BLACK.</strong></p>',17)])])}const g=n(r,[["render",a]]);export{m as __pageData,g as default};
